def calculate_walk_value(pattern):
    n = len(pattern)
    dp = [0] * (n + 1)
    dp[0] = 1

    for i in range(n):
        if pattern[i] == 'L':
            for j in range(i, -1, -1):
                dp[j + 1] += dp[j] * 2
        elif pattern[i] == 'R':
            for j in range(i, -1, -1):
                dp[j + 1] += dp[j] * 2 + 1
        elif pattern[i] == 'P':
            for j in range(i, -1, -1):
                dp[j + 1] += dp[j]
        else:  # pattern[i] == '*'
            for j in range(i, -1, -1):
                dp[j + 1] += dp[j] * 3

    return dp[n]

